// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint64 secondsAhead) public {
        vm.assume(caller != address(0));
        secondsAhead = uint64(bound(secondsAhead, 1, 1 days));

        vm.deal(caller, 20 ether);

        uint256 t0 = block.timestamp;
        vm.warp(t0 + uint256(secondsAhead));

        vm.prank(caller);
        (bool ok,) = payable(address(c)).call{value: 10 ether}("");
        require(ok, "fallback call failed");

        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}
